def git(*args):return subprocess.check_output(['git',*args],cwd=ROOT,text=True)
def read(p):return (ROOT/p).read_text()
def old(p):return git('show','HEAD:'+p)
def cards(t,prefix):
 matches=list(re.finditer(r'^### ('+prefix+r'-\d+(?:\.R\d+)?) —[^\n]+',t,re.M)); result={}
 for i,m in enumerate(matches):
  block=t[m.end():matches[i+1].start() if i+1<len(matches) else len(t)]
  deps=re.search(r'\*\*Depende de:\*\* ([^\n]+)',block).group(1).split(' **')[0]
  result[m.group(1)]={'heading':m.group(0),'dependency_text':deps,'dependencies':re.findall(r'(?:M[01]|V1)-\d+(?:\.R\d+)?',deps)}
 return result
