future=cards(read(DOCS[7]),'V1');assert len(future)==6 and future==cards(old(DOCS[7]),'V1')
combined=plan|future
def ancestors(key,active=()):
 assert key not in active,('cycle',key,active)
 result=set()
 for dep in combined[key]['dependencies']:assert dep in combined;result|={dep}|ancestors(dep,active+(key,))
 return result
for key in combined:ancestors(key)
for key in future:assert 'M1-21' in ancestors(key)
