  target=target.strip('<>')
  if re.match(r'^[a-zA-Z]+:',target) or target.startswith('#'):continue
  path=(ROOT/name).parent/unquote(target.split('#')[0]);assert path.exists() or path.resolve()==(ROOT/OUT).resolve(),(name,target);links+=1
